from pathlib import Path
import json,math,html
q=json.loads(Path('plans/auburn-octagon-town.json').read_text(encoding='utf-8'));a=json.loads(Path('artifacts/octagon-audit.json').read_text(encoding='utf-8'));b=json.loads(Path('artifacts/octagon-baseline.json').read_text(encoding='utf-8'))
P=lambda p:f"{(p['x']-4800)*.5:.2f},{(2850-p['z'])*.5:.2f}"
colors={'industrial':'#dca958','office':'#a999dd','residential':'#8abca3','commercial':'#78aede','service':'#e0a0a7'}
svg='<svg viewBox="0 0 900 850" role="img" aria-label="正八角形八片区规划总览"><rect width="900" height="850" fill="#eef2e9"/>'
for c in b['water']['data']['cells']:
 if c['water']:
  x,y=map(float,P(c).split(','));svg+=f'<rect x="{x-20}" y="{y-20}" width="40" height="40" fill="#a9d3dd"/>'
for z in q['plan']['zones']:svg+=f'<polygon points="{" ".join(P(p) for p in z["polygon"])}" fill="{colors[z["kind"]]}" opacity=".65"/>'
for r in q['plan']['roads'][:48]:svg+=f'<polyline points="{" ".join(P(p) for p in r["points"])}" fill="none" stroke="#f8faf5" stroke-width="{r["width_m"]*.5}"/><polyline points="{" ".join(P(p) for p in r["points"])}" fill="none" stroke="#66766c" stroke-width="1"/>'
for i,z in enumerate(q['plan']['zones']):
 ang=(i+.5)*math.pi/4;x=400+285*math.cos(ang);y=410-285*math.sin(ang)
 svg+=f'<text x="{x}" y="{y}" text-anchor="middle" font-size="14" font-weight="700" fill="#22372d">{z["label"]}</text>'
svg+='<text x="400" y="414" text-anchor="middle" font-size="12">中央环岛</text><text x="40" y="50" font-size="14">世界 +Z ↑ · +X →</text><text x="400" y="815" text-anchor="middle" font-size="14">南侧既有铁路；外联走廊详见实时地图，跨线形式待原生预检</text></svg>'
